import{_ as p,a0 as l,w as o,s as d,ao as r,I as t,x as a,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Python 3.9 如何修复装饰器并改进字典 | LCTT x X-CMD","titleTemplate":false,"description":"Python 3.9 如何修复装饰器并改进字典 | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Python 3.9 如何修复装饰器并改进字典 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Python 3.9 如何修复装饰器并改进字典 | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20210521 How Python 3.9 fixed decorators and improved dictionaries","title":"Python 3.9 如何修复装饰器并改进字典","tag":"202106","desc":""},"relativePath":"202106/20210521 How Python 3.9 fixed decorators and improved dictionaries.md","filePath":"[post].md"}'),h={name:"202106/20210521 How Python 3.9 fixed decorators and improved dictionaries.md"};function c(g,s,u,k,b,f){const i=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="python-3-9-如何修复装饰器并改进字典" tabindex="-1">Python 3.9 如何修复装饰器并改进字典 <a class="header-anchor" href="#python-3-9-如何修复装饰器并改进字典" aria-label="Permalink to “Python 3.9 如何修复装饰器并改进字典”">​</a></h1><blockquote><p>探索最近版本的 Python 的一些有用的特性。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202106/12/115315xrnd4evse8uzpi8i.jpg" alt=""></p><p>这是 Python 3.x 首发特性系列文章中的第十篇，其中一些版本已经发布了一段时间。Python 3.9 在 2020 年首次发布，具有很酷的新特性，但仍未被充分利用。下面是其中的三个。</p><h3 id="添加字典" tabindex="-1">添加字典 <a class="header-anchor" href="#添加字典" aria-label="Permalink to “添加字典”">​</a></h3><p>假设你有一个 <code>defaults</code> 字典，而你想更新它的参数。在 Python 3.9 之前，最好的办法是复制 <code>defaults</code> 字典，然后使用 <code>.update()</code> 方法。</p><p>Python 3.9 为字典引入了联合运算符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>defaults = dict(who=&quot;someone&quot;, where=&quot;somewhere&quot;)</span></span>
<span class="line"><span>params = dict(where=&quot;our town&quot;, when=&quot;today&quot;)</span></span>
<span class="line"><span>defaults | params</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    {&#39;who&#39;: &#39;someone&#39;, &#39;where&#39;: &#39;our town&#39;, &#39;when&#39;: &#39;today&#39;}</span></span></code></pre></div><p>注意，顺序很重要。在这种情况下，正如预期，来自 <code>params</code> 的 <code>where</code> 值覆盖了默认值。</p><h3 id="删除前缀" tabindex="-1">删除前缀 <a class="header-anchor" href="#删除前缀" aria-label="Permalink to “删除前缀”">​</a></h3><p>如果你用 Python 做临时的文本解析或清理，你会写出这样的代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def process_pricing_line(line):</span></span>
<span class="line"><span>    if line.startswith(&quot;pricing:&quot;):</span></span>
<span class="line"><span>        return line[len(&quot;pricing:&quot;):]</span></span>
<span class="line"><span>    return line</span></span>
<span class="line"><span>process_pricing_line(&quot;pricing:20&quot;)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    &#39;20&#39;</span></span></code></pre></div><p>这样的代码很容易出错。例如，如果字符串被错误地复制到下一行，价格就会变成 <code>0</code> 而不是 <code>20</code>，而且会悄悄地发生。</p><p>从 Python 3.9 开始，字符串有了一个 <code>.lstrip()</code> 方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;pricing:20&quot;.lstrip(&quot;pricing:&quot;)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    &#39;20&#39;</span></span></code></pre></div><h3 id="任意的装饰器表达式" tabindex="-1">任意的装饰器表达式 <a class="header-anchor" href="#任意的装饰器表达式" aria-label="Permalink to “任意的装饰器表达式”">​</a></h3><p>以前，关于装饰器中允许哪些表达式的规则没有得到充分的说明，而且很难理解。例如：虽然</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@item.thing</span></span>
<span class="line"><span>def foo():</span></span>
<span class="line"><span>    pass</span></span></code></pre></div><p>是有效的，而且：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@item.thing()</span></span>
<span class="line"><span>def foo():</span></span>
<span class="line"><span>    pass</span></span></code></pre></div><p>是有效的，相似地：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@item().thing</span></span>
<span class="line"><span>def foo():</span></span>
<span class="line"><span>    pass</span></span></code></pre></div><p>产生一个语法错误。</p><p>从 Python 3.9 开始，任何表达式作为装饰器都是有效的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from unittest import mock</span></span>
<span class="line"><span></span></span>
<span class="line"><span>item = mock.MagicMock()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@item().thing</span></span>
<span class="line"><span>def foo():</span></span>
<span class="line"><span>    pass</span></span>
<span class="line"><span>print(item.return_value.thing.call_args[0][0])</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    &lt;function foo at 0x7f3733897040&gt;</span></span></code></pre></div><p>虽然在装饰器中保持简单的表达式仍然是一个好主意，但现在是人类的决定，而不是 Python 分析器的选择。</p><h3 id="欢迎来到-2020-年" tabindex="-1">欢迎来到 2020 年 <a class="header-anchor" href="#欢迎来到-2020-年" aria-label="Permalink to “欢迎来到 2020 年”">​</a></h3><p>Python 3.9 大约在一年前发布，但在这个版本中首次出现的一些特性非常酷，而且没有得到充分利用。如果你还没使用，那么将它们添加到你的工具箱中。</p><hr>`,33)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),e(i,{href:"https://opensource.com/article/21/5/python-39-features"},{default:n(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/21/5/python-39-features",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),e(i,{href:"https://opensource.com/users/moshez"},{default:n(()=>[...s[2]||(s[2]=[a("Moshe Zadka",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:n(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const x=p(h,[["render",c]]);export{C as __pageData,x as default};
